// 永久接取来源与实际Advance结果一一绑定；后来取消或报告不改早先Action的完成/失败含义。
#include "task_message_return_progress.hpp"
#include "task_message_return_detail.hpp"
#include "resident/kernel/command_types.hpp"
namespace hanmo::resident {
Outcome<std::optional<TaskMessageReturnActionSource>> query_task_message_return_action(const CommonStore& c,const TaskMessageReturnState& state,const StableId& actor,const StableId& action){const auto* s=message_return_detail::start_for_action(state,action);if(!s){const auto* a=c.action(action);if(a&&a->kind==task_message_return_collect_command)return {false,{},common_failure("TaskMessageReturnActionSourceMissing",action).error};return {true,std::nullopt,{}};}if(s->carrier_actor_id!=actor||!s->actual_result)return {false,{},common_failure("TaskMessageReturnActionNotOwned",action).error};TaskMessageReturnActionSource out;out.source_identity=c.state().identity;out.actor_id=actor;out.task_id=s->task_id;out.action_id=action;out.start_fact_id=s->fact_id;out.started_tick=s->started_tick;out.session_id=s->session_id;out.dialogue_id=s->dialogue_id;out.node_id=s->node_id;out.context=s->context;out.fact_id=s->fact_id;out.status="active";const TaskMessageReturnCollection* done=nullptr;for(const auto& row:state.collections.rows())if(row.second.start_fact_id==s->fact_id){if(done)return {false,{},common_failure("DuplicateTaskMessageReturnCollection",action).error};done=&row.second;}
 if(done){if(!done->actual_result||done->tick>c.tick()||c.action(action))return {false,{},common_failure("TaskMessageReturnCompletionSourceRequired",action).error};out.status=done->success?"collected":"interrupted";out.fact_id=done->fact_id;out.reason=done->success?"TaskMessageReturnCollected":done->reason;out.completed_tick=done->tick;out.actual_result_id=done->actual_result->result_id;}else{const auto* a=c.action(action);if(!a||a->kind!=task_message_return_collect_command||a->actor_id!=actor||a->start_tick!=s->started_tick||a->remaining_ticks!=task_handover_ticks)return {false,{},common_failure("TaskMessageReturnActiveActionRequired",action).error};out.remaining_ticks=a->remaining_ticks;}return {true,std::move(out),{}};}
bool task_message_return_continuation_meeting_matches(const TaskMessageReturnActionSource& s,const InteractionSession& session){return s.status=="active"&&s.remaining_ticks==task_handover_ticks&&session.actor_id==s.actor_id&&session.id==s.session_id&&session.dialogue_id==s.dialogue_id&&session.node_id==s.node_id&&session.phase=="say"&&!session.pending_command&&session.pending_action_id.empty()&&message_return_detail::context(session.context,s.context);}
Outcome<std::optional<TaskMessageReturnActionSource>> query_task_message_return_completion(const CommonStore& c,const TaskMessageReturnState& state,const StableId& actor,const StableId& action,const ReceiptDetails& details,Integer tick,const StableId& result){auto source=query_task_message_return_action(c,state,actor,action);if(!source.ok||!source.value)return source;if(source.value->status=="active")return {true,std::nullopt,{}};const auto* advance=std::get_if<AdvanceDetails>(&details.data);const auto* e=advance?advance->completed_actions.find(action):nullptr;if(!e)return {true,std::nullopt,{}};const auto& s=*source.value;const bool success=s.status=="collected";if(result.empty()||s.actual_result_id!=result||s.completed_tick!=tick||tick>c.tick()||!e->ok||e->completed||e->success||e->already_completed||e->code||e->military||e->family||e->growth||!e->military_field_order.empty()||!e->task||e->task->task_id!=std::optional<StableId>{s.task_id}||e->task->success!=success||e->task->code!=(success?std::optional<StableId>{}:std::optional<StableId>{s.reason})||e->task->on_unavailable||e->task->retry)return {false,{},common_failure("TaskMessageReturnActualCompletionRequired",action).error};return source;}
}
